import {escapeHTML as e, available, money, toUSD, sourceGBP, unitPrice, REPORTING_FX, count, percent, signedMoney, pctChange, download, selectComparison, difference, normalizeReport} from './model.mjs';

const paths={overview:'M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h7v7h-7z',drivers:'M4 19h16 M6 15V9 M12 15V4 M18 15v-4',cohorts:'M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2 M16 3a4 4 0 0 1 0 8 M22 21v-2a4 4 0 0 0-3-3.87 M13 7a4 4 0 1 1-8 0 4 4 0 0 1 8 0',trust:'m12 3 8 4v6c0 5-8 9-8 9s-8-4-8-9V7z M8 12l3 3 5-6',memo:'M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8z M14 2v6h6 M8 13h8 M8 17h6',book:'M12 5c-3-3-7-3-10-2v16c4-1 7 0 10 2 3-2 6-3 10-2V3c-3-1-7-1-10 2z M12 5v16',download:'M12 3v12 M7 10l5 5 5-5 M5 16v5h14v-5',calendar:'M4 5h16v16H4z M8 2v6 M16 2v6 M4 11h16',globe:'M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0z M3 12h18 M12 3c4 5 4 13 0 18-4-5-4-13 0-18',reset:'M3 10a9 9 0 1 1 1 8 M3 3v7h7',clock:'M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0z M12 7v5l3 2',chevron:'m9 5 7 7-7 7',bulb:'M9 18h6 M10 22h4 M8.5 14.5a6 6 0 1 1 7 0c-1 .7-1.5 1.5-1.5 3h-4c0-1.5-.5-2.3-1.5-3z',info:'M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0z M12 11v6 M12 7h.01',money:'M12 2v20 M17 5H9a3 3 0 0 0 0 6h6a3 3 0 0 1 0 6H6',bag:'M4 7h16l1 14H3z M8 7V5a4 4 0 0 1 8 0v2',up:'m5 15 7-7 7 7 M12 8v12',down:'m5 9 7 7 7-7 M12 4v12',external:'M14 3h7v7 M10 14 11-11 M21 14v7H3V3h7',close:'m6 6 12 12 M6 18 18 6',check:'m5 12 4 4L19 6',filter:'M4 5h16 M7 12h10 M10 19h4',print:'M6 9V3h12v6 M6 18H3V9h18v9h-3 M6 14h12v8H6z',database:'M21 5c0 2-4 4-9 4S3 7 3 5s4-4 9-4 9 2 9 4z M3 5v14c0 2 4 4 9 4s9-2 9-4V5 M3 12c0 2 4 4 9 4s9-2 9-4',search:'M21 21l-5-5 M18 10a8 8 0 1 1-16 0 8 8 0 0 1 16 0',code:'m8 7-5 5 5 5 M16 7l5 5-5 5 M14 3l-4 18'};
const icon=(name,cls='')=>`<svg class="${cls}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.65" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[name]||paths.info}"/></svg>`;
const app=document.querySelector('#app');
const dialog=document.querySelector('#detail-dialog');
const pages=[['overview','Overview','Overview'],['drivers','Revenue drivers','Drivers'],['cohorts','Customer cohorts','Cohorts'],['trust','Data trust','Trust'],['memo','Decision memo','Memo']];
let data,state={page:'overview',period:'2011-11',country:'All markets',sensitivity:false},toastTimer;
const labelMonth=(month,long=false)=>new Intl.DateTimeFormat('en-GB',{month:long?'long':'short',year:'numeric',timeZone:'UTC'}).format(new Date(`${month}-01T00:00:00Z`));
const metrics=()=>selectComparison(data,state.period,state.country);
const currentPeriod=()=>data.periods.find(x=>x.id===state.period);
const deltaMarkup=(value,label='vs prior year',neutral=false)=>`<span class="change ${neutral?'neutral':Number(value)<0?'down':''}">${available(value)?icon(value<0?'down':'up')+percent(Math.abs(value)):'—'}</span><span>${e(label)}</span>`;
const safeShare=(x,total)=>total>0?x/total:null;
const shortCountry=name=>({ 'United Kingdom':'United Kingdom','EIRE':'Ireland (EIRE)','Channel Islands':'Channel Islands','United Arab Emirates':'UAE' }[name]||name);
function toast(message){const t=document.querySelector('#toast');t.textContent=message;t.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.classList.remove('show'),3300);}

function render(){
  const focused = app.contains(document.activeElement) ? document.activeElement : null;
  const focusAttribute = focused && ['id','data-page','data-action','data-sensitivity','data-chart-month'].find(attribute => focused.getAttribute(attribute));
  const focusValue = focusAttribute ? focused.getAttribute(focusAttribute) : null;
  const p=currentPeriod();
  const isFixed=state.page==='trust'||state.page==='cohorts';
  const title={overview:'Business overview',drivers:'Behind the headline',cohorts:'The next purchase',trust:'Trust, down to the source',memo:'Evidence into action'}[state.page];
  const subtitle={overview:'A clear view of recorded sales. An honest view of what changed.',drivers:'Separate arithmetic drivers, concentration, and exceptional invoices.',cohorts:'First-observed customer cohorts, with complete observation windows.',trust:'A transparent path from the original workbook to every reported number.',memo:'A recommendation grounded in the observed transactions.'}[state.page];
  app.innerHTML=`<div class="shell"><aside class="sidebar" aria-label="Main navigation"><div class="brand"><svg viewBox="0 0 36 36" aria-hidden="true"><rect width="36" height="36" rx="9" fill="#4566ed"/><path d="M8 26V18h5v8zm8 0V12h5v14zm8 0V7h5v19z" fill="#fff"/></svg><span>Revenue<span class="lens">Lens</span></span></div><div class="workspace-switch"><span class="workspace-mark">${icon('bag')}</span><span class="workspace-text">Retail intelligence</span>${icon('chevron')}</div><p class="sidebar-label">Workspace</p><nav class="nav">${pages.map(([id,name,short])=>`<button class="nav-button ${state.page===id?'active':''}" data-page="${id}" aria-label="${name}" ${state.page===id?'aria-current="page"':''}>${icon(id)}<span class="nav-label">${name}</span><span class="nav-short">${short}</span></button>`).join('')}</nav><div class="sidebar-bottom"><div class="snapshot-card"><h3>Real data. Clear boundaries.</h3><p>UCI Online Retail II<br>Historical records · 2009–2011<br>Reproducible Python + SQL</p><a class="source-link" href="https://archive.ics.uci.edu/dataset/502/online+retail+ii" target="_blank" rel="noopener noreferrer">About the dataset ${icon('external')}</a></div><button class="nav-button" data-action="dictionary">${icon('book')}<span class="nav-label">Metric dictionary</span></button><div class="sidebar-user"><span class="avatar">RL</span><span>Analyst workspace<small>Read-only evidence release</small></span></div></div></aside><div class="workspace"><header class="topbar"><div class="breadcrumb"><span>Workspace</span><span class="slash">/</span><strong>Retail intelligence</strong></div><div class="top-actions"><span class="historical">${icon('clock')}Historical dataset</span><span class="rule"></span><button class="icon-button" data-action="about" aria-label="About this report">${icon('info')}</button><span class="avatar" aria-label="RevenueLens workspace">RL</span></div></header><main id="main" class="content" tabindex="-1"><div class="lab-banner"><span><strong>Historical transaction lab · 2009–2011.</strong> These records demonstrate analytical methods; they are not current US sales.</span><a href="./index.html">Open current US report</a></div><div class="page-heading"><div><p class="eyebrow">Retail intelligence</p><h1>${title}</h1><p class="page-subtitle">${subtitle}</p></div><div class="heading-buttons">${state.page==='memo'?`<button class="button" data-action="pdf" aria-label="Download brief PDF">${icon('download')}<span>Download PDF</span></button>`:''}<button class="button" data-action="dictionary" aria-label="Metric dictionary">${icon('book')}<span>Metric dictionary</span></button><button class="button primary" aria-label="${state.page==='memo'?'Print or save decision memo as PDF':'Export evidence'}" data-action="${state.page==='memo'?'print':'export'}">${icon(state.page==='memo'?'print':'download')}<span>${state.page==='memo'?'Print / save PDF':'Export evidence'}</span></button></div></div><div class="filters">${state.page!=='trust'&&state.page!=='cohorts'?`<label class="filter">${icon('calendar')}<span class="visually-hidden">Comparison month</span><select id="period-filter">${[...data.periods].reverse().map(x=>`<option value="${e(x.id)}" ${x.id===state.period?'selected':''}>${e(x.label)}</option>`).join('')}</select></label>`:`<span class="chip blue">${icon('database')}Full observation window</span>`}${state.page!=='trust'?`<label class="filter">${icon('globe')}<span class="visually-hidden">${state.page==='cohorts'?'First-purchase country':'Country'}</span><select id="country-filter">${data.countries.map(x=>`<option value="${e(x)}" ${x===state.country?'selected':''}>${e(shortCountry(x))}</option>`).join('')}</select></label>`:''}<span class="comparison-label">${state.page==='trust'?'All source rows · filters do not change the audit':state.page==='cohorts'?'Country = first-purchase country · fixed denominators':`compared with ${e(p.previousLabel)}`}</span><div class="filter-right">${!isFixed?(state.period==='2010-12'?'<span class="chip amber">Source overlap</span>':'<span class="chip green">Complete month</span>'):''}<button class="icon-button" data-action="reset" aria-label="Reset report filters" title="Reset filters">${icon('reset')}</button></div></div><div class="currency-note"><span>Reporting currency <strong>USD</strong> <span class="currency-detail">· £1 = $1.5705 · fixed historical FX</span></span><button class="text-button" data-action="fx" aria-label="View USD conversion policy">FX policy</button></div><section id="page-content" aria-label="${title}">${pageBody()}</section><footer class="footer"><span>RevenueLens <span class="separator">·</span> Historical evidence, not live performance</span><span><a href="https://doi.org/10.24432/C5CG6D" target="_blank" rel="noopener noreferrer">Daqing Chen / UCI</a> <span class="separator">·</span> CC BY 4.0 <span class="separator">·</span> ${e(data.meta.ruleVersion||'rules-v1')}</span></footer></main></div></div>`;
  document.title=`${title} · RevenueLens`;
  attachCharts();
  if (focusAttribute) app.querySelector(`[${focusAttribute}="${CSS.escape(focusValue)}"]`)?.focus({preventScroll:true});
}
function pageBody(){if(state.page==='trust')return trustPage();if(state.page==='cohorts')return cohortsPage();const c=metrics();if(c && !available(c.delta.sales) && state.page!=='overview')return unavailableComparison(c);if(!c)return `<div class="panel empty"><h2>No comparable observations</h2><p>This country does not have an available comparison for the selected month.</p><button class="button" data-action="reset">Reset filters</button></div>`;return overlapWarning(c)+{overview:overviewPage,drivers:driversPage,memo:memoPage}[state.page](c);}
function overlapWarning(c){return state.period==='2010-12'?`<div class="callout warning" style="margin:0 0 20px"><strong>This month has overlapping source coverage.</strong> Both sheets contain records from 1–9 December 2010. The baseline retains all source rows. Under identical-content exclusion, this scope’s sales change is ${percent(c.sensitivity.deduplicatedDeltaPct)}; inspect Revenue drivers before interpreting the headline.</div>`:'';}
function banner(c){const x=c.current,y=c.previous;const d=pctChange(x.sales,y.sales);const s=c.sensitivity;const kd=difference(x.knownSales,y.knownSales),ad=difference(x.anonymousSales,y.anonymousSales);const coverage=available(kd)&&available(ad)&&kd<0&&ad>0?` Known-customer sales fell ${money(Math.abs(kd),true)}; anonymous sales rose ${money(ad,true)}.`:'';return `<div class="insight-banner"><span class="insight-icon">${icon('bulb')}</span><p><strong>${available(d)?`Recorded sales ${d>=0?'rose':'fell'} ${percent(Math.abs(d))} year over year.`:'No comparable sales base for this scope.'}</strong> ${available(s?.deltaPct)?`Excluding the five largest invoices per period leaves a ${percent(Math.abs(s.deltaPct))} ${s.deltaPct>=0?'increase':'decrease'}.`:'Inspect the invoice mix before interpreting the change.'} ${coverage} This is descriptive evidence.</p><button class="text-button" data-page="memo">Read the memo ${icon('memo')}</button></div>`;}
function kpis(c){const x=c.current,y=c.previous;return `<div class="kpi-grid">${[
 ['Positive sales',money(x.sales,true),pctChange(x.sales,y.sales),'money',false],
 ['Net merchandise movement',money(x.net,true),pctChange(x.net,y.net),'drivers',true],
 ['Sale invoices',count(x.invoices),pctChange(x.invoices,y.invoices),'bag',false],
 ['Average order value',money(x.aov),pctChange(x.aov,y.aov),'overview',false]
 ].map(([title,value,delta,ico,neutral])=>`<article class="kpi"><div class="kpi-top"><h2 class="kpi-title">${title}</h2>${icon(ico)}</div><div class="kpi-value">${value}</div><div class="kpi-foot">${deltaMarkup(delta,'vs prior year',neutral)}</div></article>`).join('')}</div>`;}
function unavailableComparison(c){return `${kpis(c)}<div class="panel empty"><h2>A fair comparison needs observations in both periods.</h2><p>One selected period has no qualifying merchandise observations for this market. The percentage change, driver attribution, and recommendation remain unavailable.</p><p>Choose a different month or market to investigate a comparable pair. Current-period invoices remain inspectable in Overview.</p><button class="button" data-page="overview">View observed data</button></div>`;}
function overviewPage(c){return `${banner(c)}${kpis(c)}<div class="chart-row"><article class="panel"><div class="panel-head"><div><h2>Sales, with the full picture</h2><p>Positive merchandise sales · USD</p></div><div class="legend"><span><i></i>Selected year</span><span><i class="previous"></i>Prior year</span></div></div><div class="line-chart-wrap">${trendChart()}</div><div class="chart-foot"><span>Same calendar months · complete months only</span><button class="text-button" data-action="trend-table">View data</button></div></article><article class="panel"><div class="panel-head"><div><h2>Where the change happened</h2><p>${state.country==='All markets'?'Country':'Product'} contribution to the sales change</p></div><button class="icon-button" data-action="bridge-help" aria-label="About country and product contributions">${icon('info')}</button></div>${available(c.delta.sales)?bridgeList(state.country==='All markets'?c.countryBridge:c.productBridge,6):'<div class="empty"><p>The comparison is unavailable because a period has no eligible observations.</p></div>'}<div class="panel-bottom"><span>Additive change · includes an Other residual</span><button class="text-button" data-page="drivers">Explore drivers</button></div></article></div><div class="bottom-row"><article class="panel"><div class="panel-head"><div><h2>Follow the evidence</h2><p>Largest sale invoices in the selected period</p></div><span class="chip">Invoice drill-through</span></div>${invoiceTable(c.topInvoices,4)}<div class="panel-bottom"><span>Source sheet and row retained for every line</span><button class="text-button" data-action="all-invoices">View all shown invoices</button></div></article><article class="panel"><div class="panel-head"><div><h2>How much can we see?</h2><p>Customer identity coverage · selected sales</p></div><button class="icon-button" data-action="coverage-help" aria-label="About anonymous customer sales">${icon('info')}</button></div>${coverageDonut(c.current)}<p class="market-note">Anonymous sales stay in overall totals. They stay outside customer counts, cohorts, and the known-customer decomposition.</p></article></div>`;}
function trendRows(){const year=Number(state.period.slice(0,4));return Array.from({length:12},(_,i)=>{const mm=String(i+1).padStart(2,'0');const get=y=>data.monthly.find(x=>x.month===`${y}-${mm}`&&x.country===state.country);return {label:new Intl.DateTimeFormat('en',{month:'short',timeZone:'UTC'}).format(new Date(`${year}-${mm}-01T00:00:00Z`)),month:`${year}-${mm}`,current:get(year),previous:get(year-1)};});}
function trendMarker(r,i,x,y){
  if(!available(r.current?.sales))return '';
  const interactive=data.periods.some(p=>p.id===r.month);
  const amount=money(r.current.sales);
  const label=`${labelMonth(r.month)}: ${amount}. ${interactive?'Select month.':'Historical context only; no comparable period available.'}`;
  const attributes=interactive?`class="chart-dot" tabindex="0" role="button" data-chart-month="${r.month}" data-tip="${e(labelMonth(r.month))}" data-tip-value="${e(amount)}"`:'class="chart-history-dot" role="img" focusable="false" fill="#fff" stroke="#5474ef" stroke-width="2"';
  return `<circle ${attributes} cx="${x(i)}" cy="${y(r.current.sales)}" r="${r.month===state.period?4.6:3.2}" aria-label="${e(label)}">${interactive?'':`<title>${e(label)}</title>`}</circle>`;
}
function trendChart(){const rows=trendRows(),W=720,H=284,L=65,R=19,T=26,B=42;const vals=rows.flatMap(x=>[x.current?.sales,x.previous?.sales]).filter(available);let maxUSD=Math.max(1,...vals.map(toUSD))*1.18;const pow=10**Math.floor(Math.log10(maxUSD));const max=Math.ceil(maxUSD/pow*2)/2*pow/REPORTING_FX.usdPerGbp;const x=i=>L+i*(W-L-R)/11,y=v=>H-B-(v/max)*(H-B-T);const path=field=>{let last=false;return rows.map((r,i)=>{const v=r[field]?.sales;if(!available(v)){last=false;return '';}const cmd=last?'L':'M';last=true;return `${cmd}${x(i).toFixed(2)},${y(v).toFixed(2)}`;}).join(' ');};const currentPath=path('current');const valid=rows.map((r,i)=>r.current&&available(r.current.sales)?i:null).filter(v=>v!==null);const continuous=valid.every((v,i)=>i===0||v===valid[i-1]+1);const area=valid.length&&continuous?`${currentPath} L${x(valid.at(-1))},${H-B} L${x(valid[0])},${H-B} Z`:'';return `<svg class="line-chart" viewBox="0 0 ${W} ${H}" role="img" aria-labelledby="trend-title trend-desc"><title id="trend-title">Monthly positive sales for ${e(state.country)}</title><desc id="trend-desc">Selected year and prior year. Missing or incomplete months are not plotted. Use View data for exact amounts.</desc><defs><linearGradient id="chart-fill" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stop-color="#5474ef" stop-opacity=".15"/><stop offset="100%" stop-color="#5474ef" stop-opacity=".01"/></linearGradient></defs>${[0,.25,.5,.75,1].map(t=>`<line class="gridline" x1="${L}" x2="${W-R}" y1="${y(max*t)}" y2="${y(max*t)}"/><text x="${L-12}" y="${y(max*t)+4}" text-anchor="end">${money(max*t,true).replace('.00','')}</text>`).join('')}${area?`<path d="${area}" fill="url(#chart-fill)"/>`:''}<path class="previous-path" d="${path('previous')}"/><path class="current-path" d="${currentPath}"/>${rows.map((r,i)=>`<text x="${x(i)}" y="${H-16}" text-anchor="middle" ${r.month===state.period?'style="fill:#4b69c6;font-weight:650"':''}>${r.label}</text>${trendMarker(r,i,x,y)}`).join('')}</svg>`;}
function bridgeList(items=[],limit=7){if(!items.length)return '<div class="empty"><p>No qualifying movements.</p></div>';const isResidual=x=>x.key==='__OTHER__'||x.name==='Other';let sorted=items.filter(x=>!isResidual(x)).sort((a,b)=>Math.abs(b.delta)-Math.abs(a.delta));let top=sorted.slice(0,limit-1);let rest=sorted.slice(limit-1).concat(items.filter(isResidual));if(rest.length)top.push({name:'Other markets / items',delta:rest.reduce((s,x)=>s+x.delta,0)});let max=Math.max(1,...top.map(x=>Math.abs(x.delta)));return `<div class="bridge-list">${top.map(x=>`<div class="bridge-item"><span class="bridge-name" title="${e(x.name)}">${e(shortCountry(x.name))}</span><div class="bridge-track"><div class="bridge-fill ${x.delta<0?'negative':''}" style="width:${Math.max(.5,Math.abs(x.delta)/max*100)}%"></div></div><span class="bridge-amount ${x.delta<0?'negative':''}">${signedMoney(x.delta)}</span></div>`).join('')}</div>`;}
function invoiceTable(items=[],limit=6){return `<div class="table-wrap"><table class="data-table"><caption class="visually-hidden">Largest sale invoices; open an invoice to see source lines.</caption><thead><tr><th>Invoice</th><th>Market</th><th>Date</th><th>Positive sales</th></tr></thead><tbody>${items.slice(0,limit).map(x=>`<tr><td><button class="invoice-btn mono" data-invoice="${e(x.id)}">#${e(x.id)}</button></td><td><span class="country-name"><span class="country-symbol">${e(x.country.slice(0,2).toUpperCase())}</span>${e(shortCountry(x.country))}</span></td><td>${e(String(x.date).slice(0,10))}</td><td class="strong">${money(x.sales)}</td></tr>`).join('')||'<tr><td colspan="4">No qualifying sale invoices.</td></tr>'}</tbody></table></div>`;}
function coverageDonut(m){const share=m.sales>0?(m.anonymousSales/m.sales):null;const known=available(share)?1-share:null;const circ=2*Math.PI*55;return `<div class="market-body"><svg class="donut" viewBox="0 0 140 140" role="img" aria-label="${available(known)?`${percent(known)} known-customer sales, ${percent(share)} anonymous sales`:'No qualifying sales'}"><circle cx="70" cy="70" r="55" fill="none" stroke="#e8edf9" stroke-width="14"/><circle cx="70" cy="70" r="55" fill="none" stroke="#536ff0" stroke-width="14" stroke-dasharray="${(known||0)*circ} ${circ}" transform="rotate(-90 70 70)" stroke-linecap="butt"/><text x="70" y="69" text-anchor="middle" fill="#374e6d" font-size="23" font-weight="650">${available(known)?percent(known,0):'—'}</text><text x="70" y="88" text-anchor="middle" fill="#94a0b1" font-size="10">known identity</text></svg><div class="market-legend"><div class="market-legend-row"><i style="background:#536ff0"></i>Known customers<strong>${percent(known)}</strong></div><div class="market-legend-row"><i style="background:#d9e1f5"></i>Anonymous<strong>${percent(share)}</strong></div><div class="market-legend-row">Purchasing customers<strong>${count(m.customers)}</strong></div></div></div>`;}

function driversPage(c){const factors=c.shapley;const s=c.sensitivity;const cur=state.sensitivity?s.currentSales:c.current.sales;const prev=state.sensitivity?s.previousSales:c.previous.sales;return `${banner(c)}<div class="section-grid"><article class="panel panel-pad"><div class="panel-head" style="padding:0"><div><h2>The known-customer bridge</h2><p>Exact Shapley attribution · six substitution orders</p></div><button class="icon-button" data-action="shapley-help" aria-label="About the sales decomposition">${icon('info')}</button></div><div style="margin-top:20px">${factors?.length?factors.map(f=>`<div class="factor-row"><div><h3>${e(f.factor)}</h3><p>${f.factor.includes('Sales')?money(f.previous):Number(f.previous).toLocaleString('en-GB',{maximumFractionDigits:2})} → ${f.factor.includes('Sales')?money(f.current):Number(f.current).toLocaleString('en-GB',{maximumFractionDigits:2})}</p></div><strong class="factor-value ${f.contribution<0?'negative':''}">${signedMoney(f.contribution)}</strong></div>`).join(''):'<div class="empty"><p>A factor has a zero denominator. Use the additive bridge below.</p></div>'}</div><div class="factor-total"><span>Known-customer sales change</span><strong>${signedMoney(difference(c.current.knownSales,c.previous.knownSales))}</strong></div><div class="callout">Anonymous sales change: <strong>${signedMoney(difference(c.current.anonymousSales,c.previous.anonymousSales))}</strong>. The factor bridge uses one consistent known-customer population. These are arithmetic contributions, not causal effects.</div></article><article class="panel panel-pad"><h2>Does the headline hold up?</h2><p class="subheading">Sensitivity to exceptionally large invoices</p><div class="sensitivity-switch" role="group" aria-label="Sensitivity view"><button data-sensitivity="false" class="${!state.sensitivity?'active':''}" aria-pressed="${!state.sensitivity}">All eligible sales</button><button data-sensitivity="true" class="${state.sensitivity?'active':''}" aria-pressed="${state.sensitivity}">Exclude top five / period</button></div><div class="comparison-pair"><div><small>${e(currentPeriod().label)}</small><strong>${money(cur,true)}</strong></div><div><small>${e(currentPeriod().previousLabel)}</small><strong>${money(prev,true)}</strong></div></div><div class="large-stat" style="margin-top:22px">${available(pctChange(cur,prev))?`${pctChange(cur,prev)>0?'+':''}${percent(pctChange(cur,prev))}`:'Unavailable'}</div><p>Year-over-year change under the selected policy</p><div class="callout warning">The same number of largest invoices is removed independently from each period. This tests sensitivity; it does not establish that those invoices are errors.</div><div class="callout">Under a separate identical-content exclusion scenario, the sales change is <strong>${available(s.deduplicatedDeltaPct)?percent(s.deduplicatedDeltaPct):'Unavailable'}</strong>. This retains one copy per content signature; the baseline preserves every distinct source row.</div></article></div><div class="section-grid"><article class="panel"><div class="panel-head"><div><h2>${state.country==='All markets'?'Country':'Product'} contributions</h2><p>Current amount minus prior amount · same scope</p></div></div>${bridgeList(state.country==='All markets'?c.countryBridge:c.productBridge,9)}<div class="panel-bottom">All contributions reconcile to ${signedMoney(c.current.sales-c.previous.sales)}.</div></article><article class="panel panel-pad"><h2>Concentration deserves a second look</h2><p class="subheading">Selected-month positive merchandise sales</p><div class="large-stat">${percent(c.concentration.top10CustomerShare)}</div><p>of known-customer sales from the top ten customers</p><div class="progress-track"><span style="width:${Math.max(0,Math.min(100,(c.concentration.top10CustomerShare||0)*100))}%"></span></div><div class="inline-stats"><div><p>Largest customer</p><strong>${percent(c.concentration.top1CustomerShare)}</strong><p>of known-customer sales</p></div><div><p>Top ten products</p><strong>${percent(c.concentration.top10ProductShare)}</strong><p>of all positive sales</p></div></div><div class="callout">Wholesale-sized baskets can move the headline. A concentrated change calls for account-level investigation before a broad retention campaign.</div></article></div><article class="panel" style="margin-bottom:23px"><div class="panel-head"><div><h2>Invoice evidence</h2><p>Inspect the recorded lines behind the largest transactions</p></div><span class="chip">Original timestamps</span></div>${invoiceTable(c.topInvoices,10)}</article>`;}

function cohortsPage(){const rows=data.cohorts[state.country]||[];const mature=rows.reduce((s,x)=>s+(x.mature90||0),0),repeat=rows.reduce((s,x)=>s+(x.repeat90||0),0),total=rows.reduce((s,x)=>s+x.size,0);const recent=rows.slice(-13);const maxOffset=11;return `<div class="insight-banner"><span class="insight-icon">${icon('cohorts')}</span><p><strong>First observed is not first ever.</strong> A cohort begins at the customer's first eligible purchase in this snapshot. The population is fixed before report filters; future and incomplete months remain unavailable.</p></div><div class="kpi-grid"><article class="kpi"><h2 class="kpi-title">First-observed customers</h2><div class="kpi-value" style="margin-top:15px">${count(total)}</div><div class="kpi-foot">Known IDs · first-purchase country</div></article><article class="kpi"><h2 class="kpi-title">Mature 90-day population</h2><div class="kpi-value" style="margin-top:15px">${count(mature)}</div><div class="kpi-foot">Full 90-day observation window</div></article><article class="kpi"><h2 class="kpi-title">90-day repurchase rate</h2><div class="kpi-value" style="margin-top:15px">${percent(safeShare(repeat,mature))}</div><div class="kpi-foot">${count(repeat)} repeat buyers / ${count(mature)}</div></article><article class="kpi"><h2 class="kpi-title">Cohort definition</h2><div class="kpi-value" style="margin-top:15px;font-size:22px">Calendar month</div><div class="kpi-foot">First eligible sale · source-local time</div></article></div><article class="panel" style="margin-bottom:22px"><div class="panel-head"><div><h2>Do customers come back?</h2><p>Monthly purchase retention · most recent 13 cohorts · fixed initial population</p></div><span class="chip blue">Observed purchases</span></div><div class="cohort-scroll"><table class="cohort-table"><caption class="visually-hidden">First-observed cohorts. Each cell is distinct buyers in the target month divided by original cohort size. Unavailable months are marked with a dash.</caption><thead><tr><th>First observed</th><th>Customers</th>${Array.from({length:maxOffset+1},(_,i)=>`<th>M${i}</th>`).join('')}</tr></thead><tbody>${recent.map(r=>`<tr><td>${labelMonth(r.cohort)}</td><td class="size">${count(r.size)}</td>${Array.from({length:maxOffset+1},(_,i)=>{const cell=r.cells.find(x=>x.offset===i);const rate=cell?.rate;const observed=available(rate);return `<td class="${observed?'':'unobserved'}" ${observed?`style="background:rgba(69,102,237,${.045+rate*.78});color:${rate>.6?'#fff':'#526d9f'}"`:''} title="${observed?`${cell.month}: ${count(cell.buyers)} / ${count(r.size)} customers = ${percent(rate)}`:'Future or incomplete month. Unavailable, not zero.'}">${observed?percent(rate,0):'—'}</td>`;}).join('')}</tr>`).join('')||'<tr><td colspan="14">No known-customer cohorts for this country.</td></tr>'}</tbody></table><div class="heatmap-legend"><span>Less</span>${[.08,.23,.4,.6,.85].map(v=>`<i style="background:rgba(69,102,237,${v})"></i>`).join('')}<span>More</span><span style="margin-left:12px">— unavailable</span></div></div><div class="panel-bottom"><span>Month 0 = 100% by construction · original cohort sizes never shrink</span><button class="text-button" data-action="cohort-export">Export all cohorts</button></div></article><div class="section-grid"><article class="panel"><div class="panel-head"><div><h2>90-day repurchase, without immature windows</h2><p>Second distinct sale invoice strictly after first timestamp</p></div></div><div class="table-wrap"><table class="data-table"><thead><tr><th>Cohort</th><th>Mature</th><th>Repeat</th><th>Rate</th></tr></thead><tbody>${recent.map(r=>`<tr><td class="strong">${labelMonth(r.cohort)}</td><td>${count(r.mature90)}</td><td>${count(r.repeat90)}</td><td class="strong">${percent(r.repeat90Rate)}</td></tr>`).join('')}</tbody></table></div></article><article class="panel panel-pad"><h2>What this evidence supports</h2><p>These rates describe repeat purchasing in the supplied historical records. They do not measure contractual churn or the effect of a retention campaign.</p><div class="callout"><strong>Observation rules</strong><br>A second product line in the same invoice is not a repeat purchase. A second invoice at the exact same timestamp is excluded by the strict rule. Only customers with 90 full observed days enter the denominator.</div><div class="callout warning"><strong>Coverage matters</strong><br>Unknown customer IDs cannot be tracked between purchases. December 2010's sheet overlap can also affect apparent activity. The Data trust page records the source-level limitations.</div><button class="text-button" style="margin-top:15px" data-page="trust">Inspect source quality ${icon('trust')}</button></article></div>`;}

function trustPage(){const q=data.quality,r=q.reconciliation;const total=q.dispositions.reduce((s,x)=>s+x.rows,0);const diff=r.difference;const pass=available(diff)&&Math.abs(diff)<.00005;const sheets=data.meta.sheets||[];return `<div class="quality-banner">${icon(pass?'check':'info')}<div><h2>${pass?'Every parsed amount has a disposition.':'The reconciliation needs review.'}</h2><p>${count(total)} source rows · ${money(diff)} unexplained parsed movement · ${count(r.unparsedRows)} rows with unparsed amounts</p></div><button class="text-button" style="margin-left:auto" data-action="audit-export">Export audit</button></div><div class="section-grid"><article class="panel panel-pad"><h2>The money reconciliation</h2><p>Signed recorded movement · full source snapshot · USD reporting</p><div class="reconciliation">${[
 ['Positive merchandise sales',r.sales],['Cancellation movement (signed)',r.cancellationMovement],['Other parsed movement',r.otherMovement],['Quarantined parsed movement',r.quarantinedMovement],['Raw parsed signed movement',r.rawMovement]
 ].map(([name,val],i)=>`<div class="rec-row ${i===4?'total':''}"><span>${name}</span><strong>${money(val)}</strong></div>`).join('')}<div class="rec-row"><span>Unexplained difference</span><strong>${money(diff)}</strong></div></div><div class="callout">Exact source checks run in integer units of 1/10,000 GBP. USD amounts apply the fixed reporting rate and round only for display. Unparseable amounts remain an unresolved row count, never an assumed zero.</div></article><article class="panel panel-pad"><h2>No silent row deletion</h2><p>Every original line receives a recorded disposition</p><div class="disposition-list">${q.dispositions.map(x=>`<div class="disposition-row"><span title="${e(x.name)}">${e(x.name.replaceAll('_',' '))}</span><div class="progress-track"><span style="width:${Math.max(1,x.rows/total*100)}%"></span></div><strong>${count(x.rows)}</strong></div>`).join('')}</div><div class="inline-stats"><div><p>Duplicate candidate rows</p><strong>${count(q.duplicateCandidates.rows)}</strong><p>Retained, not automatically deleted</p></div><div><p>Collision invoices</p><strong>${count(q.collisions.invoices)}</strong><p>Quarantined from sale metrics</p></div></div></article></div><div class="section-grid"><article class="panel panel-pad"><h2>One original workbook. Two sheets.</h2><dl class="source-grid"><div><dt>Dataset</dt><dd>UCI Online Retail II</dd></div><div><dt>Creator / licence</dt><dd>Daqing Chen · CC BY 4.0</dd></div><div><dt>Source rows</dt><dd>${count(total)}</dd></div><div><dt>Rules</dt><dd>${e(data.meta.ruleVersion||'rules-v1')}</dd></div>${sheets.map(s=>`<div><dt>${e(s.name||s.sheet||'Worksheet')}</dt><dd>${count(s.rows||s.rowCount||s.row_count)} rows</dd></div>`).join('')}<div class="full"><dt>Workbook SHA-256</dt><dd class="hash mono">${e(data.meta.sha256||data.meta.workbookSha256||data.meta.sourceSha256||'See data/manifest.json in the source release')}</dd></div></dl><button class="text-button" data-action="about">Full source and methodology ${icon('book')}</button></article><article class="panel panel-pad"><h2>The limits travel with the numbers</h2><p>The sheets overlap in early December 2010. Identical content is flagged and retained because repeated rows do not, by themselves, establish a duplicate transaction. Prefer the November default comparison.</p><p>Invoices with inconsistent customer, country, or timestamp are quarantined. Missing IDs stay as an unknown member. Non-merchandise codes and unusual signs are separated from eligible sales.</p><div class="callout warning">Cancellations are recorded movements. They are not matched to original sales; the cancellation value ratio is not an order return probability. No source timezone, margin, website conversion, or campaign lift is inferred.</div></article></div><article class="panel" style="margin-bottom:23px"><div class="panel-head"><div><h2>Exceptions you can inspect</h2><p>Examples from the issue log · original sheet and row ordinal</p></div></div><div class="table-wrap"><table class="data-table"><thead><tr><th>Source row</th><th>Invoice / product</th><th>Disposition</th><th>Signed movement</th></tr></thead><tbody>${q.samples.filter(x=>!['sale','cancellation'].includes(x.disposition)).slice(0,12).map(x=>`<tr><td>${e(x.sheet)}:${count(x.row)}</td><td class="mono">${e(x.invoice)} / ${e(x.stock)}</td><td title="${e(x.reason)}">${e(x.disposition.replaceAll('_',' '))}</td><td>${money(x.amount)}</td></tr>`).join('')}</tbody></table></div></article>`;}

function memoPage(c){const x=c.current,y=c.previous;const delta=pctChange(x.sales,y.sales),s=c.sensitivity;const bridge=[...(state.country==='All markets'?c.countryBridge:c.productBridge)].sort((a,b)=>Math.abs(b.delta)-Math.abs(a.delta));const lead=bridge[0];const topFactor=c.shapley?.length?[...c.shapley].sort((a,b)=>Math.abs(b.contribution)-Math.abs(a.contribution))[0]:null;const sensitive=available(delta)&&available(s.deltaPct)&&Math.sign(delta)!==Math.sign(s.deltaPct);return `<div class="memo"><article class="panel" style="margin-bottom:24px"><div class="memo-cover"><p class="memo-tag">Commercial decision brief</p><h2>${available(delta)?`Sales ${delta>=0?'grew':'declined'}. Validate the mix before choosing the intervention.`:'Build the comparison base before choosing an intervention.'}</h2><div class="memo-meta"><span>${e(currentPeriod().label)} vs ${e(currentPeriod().previousLabel)}</span><span>${e(state.country)}</span><span>Historical analysis · USD</span></div><p class="memo-intro">Recorded positive merchandise sales were <strong>${money(x.sales)}</strong>, compared with <strong>${money(y.sales)}</strong> in the prior-year month. ${available(delta)?`The ${percent(Math.abs(delta))} ${delta>=0?'increase':'decrease'} is an observed change in this snapshot.`:'The prior-period denominator does not support a percentage change.'} It does not establish the effect of pricing, a campaign, or customer experience.</p><div class="memo-findings"><div class="memo-finding"><strong>${signedMoney(difference(x.sales,y.sales))}</strong><small>Positive-sales change</small></div><div class="memo-finding"><strong>${money(x.cancellations,true)}</strong><small>Cancellation value · separate flow</small></div><div class="memo-finding"><strong>${percent(x.anonymousShare)}</strong><small>Anonymous share of positive sales</small></div></div></div><section class="memo-section"><h3>What the evidence says</h3><ul><li><strong>The change has identifiable contributors.</strong> ${lead?`${e(lead.name)} contributes ${signedMoney(lead.delta)} to the positive-sales difference. The complete additive bridge reconciles to the headline.`:'There is no segment movement to attribute.'} ${topFactor?`Within known customers, the largest absolute Shapley contribution is ${e(topFactor.factor.toLowerCase())}, at ${signedMoney(topFactor.contribution)}.`:'The multiplicative decomposition is unavailable where a denominator is zero.'}</li><li><strong>Large transactions deserve direct review.</strong> ${percent(c.concentration.top10CustomerShare)} of selected known-customer sales comes from the top ten customers. Excluding five largest invoices separately in each month gives ${available(s.deltaPct)?`${percent(Math.abs(s.deltaPct))} ${s.deltaPct>=0?'growth':'decline'}`:'an unavailable percentage comparison'}. ${sensitive?'The direction changes: the headline is sensitive to these transactions.':'Compare this result with the full-data headline before generalizing.'}</li><li><strong>Customer interpretation has a coverage boundary.</strong> Anonymous purchases account for ${percent(x.anonymousShare)} of selected positive sales. They contribute to the business total but cannot support a customer-level retention claim.</li></ul></section><section class="memo-section"><h3>Recommendation and next action</h3><p>Start with an invoice and account review of the largest contributors. Confirm whether they represent recurring wholesale demand, one-off baskets, cancellations, or data issues. Use the invoice evidence in this report to ground that review.</p><p>Before funding a general retention campaign, inspect mature customer cohorts and specify a customer-level randomized holdout with a fixed observation window, a minimum useful repurchase effect, and contact-cost guardrails. This dataset cannot tell us whether that intervention would work.</p><button class="text-button" data-page="drivers">Inspect the driver evidence ${icon('drivers')}</button></section><section class="memo-section"><h3>Alternative explanations and evidence that would change the decision</h3><p>A customer-count change, a different invoice mix, and a change in recorded prices can all move sales. Known-customer sales changed by ${signedMoney(difference(x.knownSales,y.knownSales))}; anonymous sales changed by ${signedMoney(difference(x.anonymousSales,y.anonymousSales))}. A change concentrated in anonymous purchases does not establish improved known-customer retention. The Shapley bridge allocates an arithmetic identity; it cannot distinguish underlying causes. Validate source completeness, ask account owners about exceptional purchases, and obtain campaign exposure or a randomized assignment before asserting lift.</p><p>Keep the recommendation provisional if the sensitivity changes direction, the customer cohort is immature, or source collisions materially affect the selected period. A credible decision can be to gather more evidence.</p></section><section class="memo-section"><h3>Measurement boundaries</h3><p>Positive sales and net recorded merchandise movement are operational measures, not audited revenue recognition or profit. Cancellations are not linked to original purchases. First-observed customers may have bought before the snapshot began. December 2010 contains overlapping source coverage. No margin, CAC, ROAS, acquisition date, current commercial performance, or achieved campaign impact is claimed.</p><p class="mono" style="font-size:11px;overflow-wrap:anywhere">Source: Chen, D. (2012), UCI Online Retail II · DOI 10.24432/C5CG6D · CC BY 4.0<br>Snapshot SHA-256: ${e(data.meta.sha256||data.meta.workbookSha256||data.meta.sourceSha256||'data/manifest.json')}</p><p class="print-only">Generated from the selected report filters. The source package includes SQL, classification rules, fixture tests, and exact reconciliation artifacts.</p></section></article></div>`;}

const dictionary=[
 ['Positive merchandise sales','Sum of quantity × positive unit price for eligible, non-cancellation merchandise sale lines. Unknown customer IDs remain included. Display: USD at fixed reporting FX; source: GBP.','Additive across disjoint source lines; repeated content is retained.'],
 ['Cancellation value','Absolute magnitude of negative movement on eligible cancellation-prefixed merchandise lines. Shown as a positive value; not matched to original invoices.','Cancellation value divided by sales is a movement ratio, not an order return probability.'],
 ['Net merchandise movement','Positive merchandise sales minus cancellation value under identical filters.','This is recorded merchandise movement, not audited net revenue or margin.'],
 ['Sale invoices','Distinct validated invoice keys with at least one eligible sale line in the period and country.','Inconsistent customer, country, or timestamps quarantine the affected invoice. Line count is not an order count.'],
 ['Average order value','Positive merchandise sales divided by qualifying sale invoices, using the same filter.','A zero denominator is unavailable. Do not average subgroup AOVs without invoice weights.'],
 ['Known purchasing customers','Distinct non-missing customer IDs with at least one eligible sale invoice in the selected period.','The unknown customer is excluded; this is observed purchasing, not true acquisition.'],
 ['Anonymous sales share','Eligible positive sales without a customer ID divided by all eligible positive sales.','An identity coverage measure. Anonymous sales are not deleted.'],
 ['Known-customer Shapley decomposition','Known sales = purchasing customers × invoices per purchasing customer × positive sales per invoice. Contributions average all six factor substitution orders.','Uses known customers for every factor. Exact arithmetic allocation does not establish causality. Zero denominators make the multiplicative bridge unavailable.'],
 ['Country / product contribution','Current positive sales minus prior positive sales for each country or product. All contributions, including Other, sum to the headline change.','Country is the recorded transaction country; cohort country is separately fixed at first purchase.'],
 ['Monthly purchase retention','Distinct cohort members with an eligible sale in the target calendar month divided by the fixed initial cohort size. Cohort = first observed eligible purchase month.','Month zero is 100%. Only complete months are published. Future or partial months are unavailable.'],
 ['90-day repurchase rate','Mature customers with a second distinct eligible invoice strictly after their first invoice timestamp, within 90 days, divided by all mature customers.','A customer needs 90 full observed days. Same-invoice extra product lines and same-timestamp invoices do not count as repeats.'],
 ['Concentration','Top customer shares use known-customer positive sales as the denominator. Product concentration uses all positive merchandise sales.','Selected month and market, with missing denominators unavailable.'],
 ['Exceptional invoice sensitivity','Remove the five largest eligible sale invoices independently in each comparison period and recompute positive sales and the percentage change.','This is a sensitivity check, not an assertion that excluded invoices are invalid.'],
 ['Unavailable versus zero','A zero is an observed amount or rate with source coverage and a valid denominator. Unavailable means the observation or denominator cannot support the metric.','December 2011 is incomplete. It is excluded from complete-month comparisons and cohort cells.']
];
function openDialog(title,subtitle,body){dialog.innerHTML=`<div class="dialog-head"><div><h2 id="dialog-title">${e(title)}</h2><p>${e(subtitle)}</p></div><button class="icon-button" data-action="close-dialog" aria-label="Close dialog">${icon('close')}</button></div><div class="dialog-content">${body}</div>`;dialog.showModal();}
function showFX(){openDialog('USD reporting currency','One transparent rate, consistent comparisons',`<h3>GBP 1 = USD 1.5705</h3><p>The reference is November 30, 2011, from the Federal Reserve H.10 series <a href="https://fred.stlouisfed.org/data/DEXUSUK" target="_blank" rel="noopener noreferrer">DEXUSUK, published by FRED</a>. This is the month-end reference for the default investigation.</p><p>Every monetary amount in the dashboard applies this same rate, including both comparison periods. Percentage changes, customer counts, shares, and cohort rates are unchanged. Converted values round for display; exact reconciliation remains in the original GBP units.</p><h3>The evidence keeps its original currency</h3><p>Invoice details and evidence CSVs include original GBP amounts. The downloaded source audit and reproducible SQL artifacts remain GBP. The dataset describes a UK-based retailer; presenting it in USD does not turn it into US market data.</p><p>This is a fixed historical reporting convention. It is not current FX, transaction-date conversion, or a claim about foreign-exchange gains.</p>`);}
function showDictionary(){openDialog('The metric dictionary','Definitions, denominators, and boundaries',`<label><span class="visually-hidden">Search metric definitions</span><input class="dictionary-search" id="dictionary-search" placeholder="Search metrics, cohorts, cancellations…" type="search"></label><div id="dictionary-items">${dictionary.map(([name,def,note])=>`<article class="dictionary-item" data-search="${e([name,def,note].join(' ').toLowerCase())}"><h3>${e(name)}</h3><p>${e(def)}</p><small>${e(note)}</small></article>`).join('')}</div>`);}
function showInvoice(id){const x=data.invoices[id];if(!x){toast('Source detail is not included for this invoice.');return;}openDialog(`Invoice #${id}`,'USD reporting · original GBP evidence retained · source-local timestamps',`<div class="dialog-stats"><div><small>Recorded date</small><strong>${e(String(x.date).replace('T',' '))}</strong></div><div><small>Market</small><strong>${e(shortCountry(x.country))}</strong></div><div><small>Customer</small><strong>${e(x.customer||'Unknown')}</strong></div><div><small>Eligible positive sales</small><strong>${money(x.sales)}</strong></div></div><p class="record-note">${count(x.lineCount)} eligible sale lines. Original source ordinal and GBP amounts are retained. USD uses the fixed reporting rate. ${x.items.length<x.lineCount?`Showing the first ${count(x.items.length)} source lines; this preview is truncated.`:'All eligible sale lines for this invoice are shown.'} Identical content on different source rows is retained.</p><div class="dialog-table"><table class="data-table"><thead><tr><th>Product</th><th>Description</th><th>Quantity</th><th>Unit price USD</th><th>Amount USD</th><th>Source GBP</th><th>Source row</th></tr></thead><tbody>${x.items.map(l=>`<tr><td class="mono">${e(l.stock)}</td><td>${e(l.description)}</td><td>${count(l.quantity)}</td><td>${unitPrice(l.price)}</td><td>${money(l.amount)}</td><td>${sourceGBP(l.amount)}</td><td style="font-size:10px;white-space:nowrap">${e(l.sheet)}<br>row ${count(l.row)}</td></tr>`).join('')}</tbody></table></div><div class="callout">The workbook does not establish fulfilment, margin, or a causal business explanation. This drill-through supports inspection of the recorded transaction.</div>`);}
function csvCell(v){if(typeof v==='number')return Number.isFinite(v)?String(v):'';let str=String(v??'');if(/^[=+\-@\t\r]/.test(str))str="'"+str;return '"'+str.replaceAll('"','""')+'"';}
function csv(rows){return '\uFEFF'+rows.map(r=>r.map(csvCell).join(',')).join('\r\n');}
function exportEvidence(){
 const c=metrics();if(!c){toast('No comparison available to export.');return;}
 const monetary=new Set(['sales','cancellations','net','aov','knownSales','anonymousSales']);
 const rows=[['RevenueLens evidence export'],['Source','UCI Online Retail II / Daqing Chen / CC BY 4.0'],['Reporting currency','USD'],['Source currency','GBP'],['Reporting FX: USD per GBP',REPORTING_FX.usdPerGbp],['FX reference date',REPORTING_FX.referenceDate],['FX reference',REPORTING_FX.sourceUrl],['FX method','One fixed rate applied to every period; not daily conversion or current FX'],['Historical comparison',currentPeriod().label,currentPeriod().previousLabel],['Market',state.country],['Comparison status',available(c.delta.sales)?'Comparable eligible observations':'Unavailable: at least one period has no eligible observations'],['Measure','Unit','Current','Prior','Original current GBP','Original prior GBP'],...['sales','cancellations','net','invoices','aov','customers','knownSales','anonymousSales','anonymousShare'].map(k=>[k,monetary.has(k)?'USD':k==='anonymousShare'?'Fraction':'Count',monetary.has(k)?toUSD(c.current[k]):c.current[k],monetary.has(k)?toUSD(c.previous[k]):c.previous[k],monetary.has(k)?c.current[k]:'',monetary.has(k)?c.previous[k]:'']),[],['Segment','Current USD','Prior USD','Change USD','Original current GBP','Original prior GBP','Original change GBP'],...(available(c.delta.sales)?(state.country==='All markets'?c.countryBridge:c.productBridge).map(x=>[x.name,toUSD(x.current),toUSD(x.previous),toUSD(x.delta),x.current,x.previous,x.delta]):[['Unavailable comparison: no additive change is reported']]),[],['Limitations','Recorded merchandise movement, not audited revenue. Historical UK retail in USD presentation. Descriptive, not causal. IDs may be missing. December 2010 contains overlapping source coverage.']];
 download(csv(rows),`RevenueLens-USD-${state.period}-${state.country.replaceAll(' ','-')}.csv`,'text/csv;charset=utf-8');toast('USD evidence and original GBP amounts exported.');
}
function exportCohorts(){const rows=[['RevenueLens fixed first-observed cohorts',state.country],['Cohort','Initial customers','Mature 90-day customers','Repeat within 90 days','90-day rate','Activity month','Month offset','Buyers','Monthly rate'],...(data.cohorts[state.country]||[]).flatMap(r=>r.cells.map(c=>[r.cohort,r.size,r.mature90,r.repeat90,r.repeat90Rate,c.month,c.offset,c.buyers,c.rate]))];download(csv(rows),`RevenueLens-cohorts-${state.country.replaceAll(' ','-')}.csv`,'text/csv;charset=utf-8');toast('Fixed cohort data exported.');}
function showTrendTable(){const rows=trendRows();openDialog('The trend, in numbers',`${state.country} · USD · unavailable is not zero`,`<div class="dialog-table"><table class="data-table"><thead><tr><th>Month</th><th>Selected year</th><th>Prior year</th></tr></thead><tbody>${rows.map(r=>`<tr><td>${r.label}</td><td>${money(r.current?.sales)}</td><td>${money(r.previous?.sales)}</td></tr>`).join('')}</tbody></table></div><p>Only complete observed months are plotted. The December 2010 source overlap is retained and disclosed. The December 2011 partial month is not plotted.</p>`);}
function about(){openDialog('An investigation you can reproduce','RevenueLens · a historical retail analysis',`<h3>USD reporting, original GBP evidence</h3><p>All dashboard amounts use one fixed historical reporting rate: GBP 1 = USD 1.5705, referenced to Federal Reserve H.10 / FRED DEXUSUK on November 30, 2011. Applying the same rate to both periods preserves percentage changes. This is a constant-currency presentation, not transaction-date conversion or live FX. The underlying dataset remains UK retail, with original GBP values in the source audit and invoice evidence.</p><h3>Built from the full source</h3><p>This report is generated from UCI Online Retail II, not seeded dashboard numbers. The source package includes the immutable source manifest, Python classification pipeline, SQLite star schema and SQL marts, exact reconciliation artifacts, and hand-checkable fixture tests.</p><h3>One coherent path to evidence</h3><p>Choose a complete comparison month and market. Read the headline, investigate arithmetic drivers and concentration, inspect source invoice lines, check mature cohorts, and finish with a decision brief. The audit always covers the complete snapshot; cohort populations remain fixed.</p><h3>Deliberate release boundaries</h3><p>This read-only application publishes aggregate historical data and a bounded set of invoice evidence. It does not connect to a live retailer or perform commercial actions. A browser report makes the analysis accessible without Power BI licences. The source package includes optional Power BI modelling guidance; a native PBIX is not part of this release.</p><h3>Source and attribution</h3><p>Chen, D. (2012). <a href="https://doi.org/10.24432/C5CG6D" target="_blank" rel="noopener noreferrer">Online Retail II</a>. UCI Machine Learning Repository. Licensed under <a href="https://creativecommons.org/licenses/by/4.0/" target="_blank" rel="noopener noreferrer">CC BY 4.0</a>. Amounts are sterling; workbook timestamps remain source-local because no reliable timezone is supplied. The sheets overlap in early December 2010.</p><p class="mono" style="font-size:11px;overflow-wrap:anywhere">Workbook SHA-256: ${e(data.meta.sha256||data.meta.workbookSha256||data.meta.sourceSha256||'See data/manifest.json')}<br>Rule version: ${e(data.meta.ruleVersion||'rules-v1')}</p>`);}

async function exportBriefPDF(button){
  const memo=document.querySelector('.memo');
  if(!memo||button.disabled)return;
  const snapshot=memo.cloneNode(true);
  const options={title:'Historical retail decision memo',filename:`RevenueLens-historical-${state.period}-${state.country.replace(/[^a-z0-9]+/gi,'-')}.pdf`,contextLines:[`Historical transaction lab: 2009-2011; not current US sales`, `Comparison month: ${state.period} | Market: ${state.country}`, `Reporting currency: USD | GBP 1 = USD 1.5705 | Fixed historical FX, November 30, 2011`]};
  button.disabled=true;button.setAttribute('aria-busy','true');
  try{
    const {downloadBriefPDF}=await import('./brief-pdf.mjs');
    await downloadBriefPDF(snapshot,options);
    toast('Selected brief PDF downloaded.');
  }catch(error){
    console.error('Brief PDF export failed',error);
    toast('PDF download failed. Please try again or use Print brief.');
  }finally{
    if(button.isConnected){button.disabled=false;button.removeAttribute('aria-busy');}
  }
}

document.addEventListener('click',event=>{const b=event.target.closest('button,a');if(!b)return;if(b.dataset.page){state.page=b.dataset.page;setURL();render();window.scrollTo({top:0,behavior:'instant'});return;}if(b.dataset.invoice){showInvoice(b.dataset.invoice);return;}if(b.dataset.sensitivity!==undefined){state.sensitivity=b.dataset.sensitivity==='true';render();return;}switch(b.dataset.action){case 'dictionary':showDictionary();break;case 'fx':showFX();break;case 'close-dialog':dialog.close();break;case 'about':about();break;case 'reset':state={page:state.page,period:'2011-11',country:'All markets',sensitivity:false};setURL();render();toast('Filters reset to the documented baseline.');break;case 'export':if(state.page==='trust')exportAudit();else if(state.page==='cohorts')exportCohorts();else exportEvidence();break;case 'pdf':void exportBriefPDF(b);break;case 'print':window.print();break;case 'cohort-export':exportCohorts();break;case 'audit-export':exportAudit();break;case 'trend-table':showTrendTable();break;case 'all-invoices':openDialog('Largest sale invoices',`${currentPeriod().label} · ${state.country}`,invoiceTable(metrics().topInvoices,30));break;case 'bridge-help':openDialog('An additive bridge','Amounts, not inferred causes','<p>Each contribution is the current period’s positive sales minus the comparison period’s positive sales for that segment. All segments sum to the headline change. The chart ranks the largest absolute contributions and groups the remainder into Other.</p>');break;case 'coverage-help':openDialog('Customer coverage','Overall business totals and customer-level analysis have different populations','<p>Valid anonymous sales belong in overall merchandise totals. Without customer IDs they cannot be linked over time, so they are excluded from purchasing-customer counts, the factor decomposition, and customer cohorts. Known-customer shares use known sales as their denominator.</p>');break;case 'shapley-help':openDialog('An exact identity, carefully interpreted','Three factors · six possible substitution orders','<p>Known-customer sales equal purchasing customers multiplied by invoices per purchasing customer multiplied by positive sales per invoice. The Shapley attribution replaces each factor from its prior value to its current value in all six possible orders and averages the incremental contributions.</p><p>The contributions sum to the observed known-customer sales change. They allocate arithmetic change; they do not prove why customers, frequency, or order values changed. If any denominator is zero, the factor bridge remains unavailable.</p>');break;}});
function exportAudit(){download(JSON.stringify({source:data.meta,reportingCurrency:REPORTING_FX,note:'All audit numeric amounts remain original source GBP; browser displays converted USD.',quality:data.quality},null,2),'RevenueLens-source-audit.json','application/json');toast('Full-snapshot source audit exported.');}
document.addEventListener('change',event=>{if(event.target.id==='period-filter'){state.period=event.target.value;setURL();render();}if(event.target.id==='country-filter'){state.country=event.target.value;setURL();render();}});
document.addEventListener('input',event=>{if(event.target.id==='dictionary-search'){const q=event.target.value.toLowerCase();document.querySelectorAll('.dictionary-item').forEach(x=>x.hidden=!x.dataset.search.includes(q));}});
dialog.addEventListener('click',event=>{if(event.target===dialog){const r=dialog.getBoundingClientRect();if(event.clientX<r.left||event.clientX>r.right||event.clientY<r.top||event.clientY>r.bottom)dialog.close();}});
function attachCharts(){document.querySelectorAll('[data-chart-month]').forEach(dot=>{const show=()=>{document.querySelector('.chart-tooltip')?.remove();const t=document.createElement('div');t.className='chart-tooltip';t.innerHTML=`${e(dot.dataset.tip)}<small>Positive sales: ${e(dot.dataset.tipValue)}</small>`;const r=dot.getBoundingClientRect();t.style.left=`${Math.min(window.innerWidth-230,Math.max(10,r.x-80))}px`;t.style.top=`${Math.max(10,r.y-70)}px`;document.body.append(t);};const hide=()=>document.querySelector('.chart-tooltip')?.remove();dot.addEventListener('pointerenter',show);dot.addEventListener('pointerleave',hide);dot.addEventListener('focus',show);dot.addEventListener('blur',hide);const choose=()=>{if(data.periods.some(p=>p.id===dot.dataset.chartMonth)){hide();state.period=dot.dataset.chartMonth;setURL();render();}};dot.addEventListener('click',choose);dot.addEventListener('keydown',ev=>{if(ev.key==='Enter'||ev.key===' '){ev.preventDefault();choose();}});});}
function setURL(){const url=new URL(location.href);url.searchParams.set('view',state.page);url.searchParams.set('month',state.period);if(state.country==='All markets')url.searchParams.delete('country');else url.searchParams.set('country',state.country);history.replaceState(null,'',url);}
function readURL(){const q=new URLSearchParams(location.search);if(pages.some(p=>p[0]===q.get('view')))state.page=q.get('view');if(data.periods.some(p=>p.id===q.get('month')))state.period=q.get('month');if(data.countries.includes(q.get('country')))state.country=q.get('country');}
async function boot(){try{const response=await fetch('./data/dashboard.json');if(!response.ok)throw new Error(`Snapshot request failed (${response.status})`);data=normalizeReport(await response.json());readURL();render();}catch(err){app.innerHTML=`<main class="error-state"><p class="eyebrow">RevenueLens</p><h1>The evidence snapshot could not be opened.</h1><p>The report needs its generated data/dashboard.json file. If you are running locally, follow the build commands in the README and serve the dist directory through HTTP.</p><p>${e(err.message)}</p><button class="button primary" id="retry-load">Retry loading</button></main>`;document.querySelector('#retry-load').addEventListener('click',boot);}}
boot();
